<h3 id="cmb-activity">Recent calls</h3>
<?php $stateNames=['announcing'=>'Playing greeting','queued'=>'Waiting','starting'=>'Calling back','authenticating'=>'Checking account','dialling'=>'Dialling destination','connected'=>'Connected','completed'=>'Completed','failed'=>'Did not connect','cancelled'=>'Cancelled'];$resultNames=['admin_cancelled'=>'Cancelled by administrator','authentication_failed'=>'Authentication unsuccessful','account_busy'=>'Account already has a call','interrupted_before_destination'=>'Interrupted before destination; no minutes charged','quota_exhausted'=>'No minutes available','destination_refused'=>'Number not allowed','destination_blocked'=>'Number not allowed','caller_unavailable'=>'Caller did not answer','caller_no_answer'=>'Caller did not answer','caller_disconnected'=>'Caller disconnected','caller_route_blocked'=>'No permitted route to the caller','destination_no_answer'=>'Destination did not answer','connected'=>'Call completed','completed'=>'Call completed','service_unavailable'=>'Callback number is unavailable','domain_unavailable'=>'Phone domain needs attention','greeting_missing'=>'Company greeting needs attention','identity_key_unavailable'=>'Private account authentication needs attention','cancelled'=>'Service or account was switched off','request_expired'=>'Callback request expired','launch_refused'=>'Callback could not start','interrupted_review_usage'=>'Interrupted; review charged minutes','answer_accounting_uncertain'=>'Answer accounting uncertain; review charged minutes','internal_failure'=>'Callback could not complete'];$rows=[];foreach($cmb['recent_attempts']as$r){ob_start();if($r['state']==='queued'&&(int)$r['reserved_seconds']===0): ?><form method="post" class="setup-form"><?php $cmbAction('cancel_request',['request_uuid'=>$r['request_uuid']]); ?><button class="setup-button" type="submit">Cancel callback</button></form><?php endif;$button=ob_get_clean();$result=$r['last_result']===''?'':($resultNames[$r['last_result']]??'See call status');$rows[]=[$e($r['created_at']),$e($r['service_name']),$e($r['caller_number']),$e($r['account_name']??'Not yet authenticated'),$e($stateNames[$r['state']]??'Processing'),$cmbMinutes($r['used_seconds']),$e($result),$button];}$table(['Time','Callback number','Caller','Account','Status','Used min','Result','Action'],$rows); ?>
<p class="setup-hint">The latest 100 requests are shown. Requests already being called cannot be cancelled here. The system never retries a completed request as a new call automatically.</p>
<p class="setup-hint">Completed callback history and old revoked callers are automatically removed after each service’s retention period (90 days by default). Saved callers remain until revoked or deleted. Administrator changes have a separate 365-day audit containing only administrator and item identifiers, action names and times. Account identity deletion preserves cumulative minute totals and usage records.</p>
